<?php
if (!isset($u['id'])) { http_response_code(404); exit; }
$msgs=rows('SELECT m.*,a.nombre remitente,b.nombre destinatario FROM mensajes m JOIN usuarios a ON a.id=m.remitente_id JOIN usuarios b ON b.id=m.destinatario_id WHERE m.remitente_id=? OR m.destinatario_id=? ORDER BY m.creado DESC,m.id DESC LIMIT 100',[$u['id'],$u['id']]);
?><?php if(!$msgs): ?><p class="empty">Tu primera conversación comienza aquí.</p><?php endif; foreach($msgs as $m): ?><details class="message" data-message-id="<?=h($m['id'])?>"><summary><span class="pill"><?=$m['remitente_id']==$u['id']?'Enviado':($m['leido']?'Recibido':'Sin leer')?></span><strong><?=h($m['asunto'])?></strong><small><?=h($m['remitente'])?> → <?=h($m['destinatario'])?></small></summary><p class="pre"><?=h($m['cuerpo'])?></p><small><?=h($m['creado'])?></small><?php if($m['destinatario_id']==$u['id'] && !$m['leido']): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=h($m['id'])?>"><button class="secondary small">Marcar como leído</button></form><?php endif; ?></details><?php endforeach; ?>
